/* str tests: the CPython corpus (str_corpus.h, generated by gen_str_corpus.py quoted in that file), exhaustive
 * code-point hashes against CPython, randomized comparisons with naive references for the search algorithms, and
 * hand-written edge cases (invalid UTF-8, builder, arena results). */
#include "dk/dk.h"
#include "dk/test.h"

#include <math.h>

#include "str_corpus.h"

static DkStr L(CLit c) { return dk_strn(c.p, c.n); }
static bool same(DkStr s, CLit c) { return s.n == c.n && (c.n == 0 || memcmp(s.p, c.p, c.n) == 0); }

/* At most a few failures per family are printed, so that one broken function does not bury the log. */
static int g_printed;
#define BAD(...)                                              \
    do {                                                      \
        if (g_printed++ < 12) CHECK_MSG(false, __VA_ARGS__);  \
        else dk_test__failed_checks++;                       \
    } while (0)
#define FAMILY_START() (g_printed = 0)

static const char *show(CLit c) { return dk_sprintf(dk_scratch(), "%.*s", (int)c.n, c.p); }
static const char *show_s(DkStr s) { return dk_sprintf(dk_scratch(), "%.*s", (int)s.n, s.p); }

static bool vec_matches(const DkStrVec *v, unsigned off, unsigned cnt) {
    if (v->n != cnt) return false;
    for (unsigned i = 0; i < cnt; i++)
        if (!same(v->v[i], corpus_pool[off + i])) return false;
    return true;
}

DK_TEST(corpus_split) {
    FAMILY_START();
    for (size_t i = 0; i < DK_ARRAY_LEN(corpus_split); i++) {
        const split_case *c = &corpus_split[i];
        DkStrVec v = dk_str_split(L(c->s), c->none ? DK_S("") : L(c->sep), c->maxsplit);
        if (!vec_matches(&v, c->off, c->cnt))
            BAD("split case %zu: s=\"%s\" sep=\"%s\" none=%d max=%d: got %zu fields, want %u", i, show(c->s), show(c->sep), c->none,
                c->maxsplit, v.n, c->cnt);
        dk_vec_free(&v);
    }
}

