DK_TEST(corpus_parse_int) {
    FAMILY_START();
    for (size_t i = 0; i < DK_ARRAY_LEN(corpus_int); i++) {
        const int_case *c = &corpus_int[i];
        i64 v = 12345;
        bool ovf = true;
        bool ok = dk_parse_int(L(c->s), c->base, &v, &ovf);
        bool good = c->status == 0 ? (ok && v == c->val && !ovf) : c->status == 1 ? (!ok && !ovf) : (!ok && ovf);
        if (!good) BAD("int case %zu: \"%s\" base %d: ok=%d ovf=%d v=%lld, want status %d val %lld", i, show(c->s), c->base, ok, ovf, (long long)v, c->status, c->val);
        u64 u = 0;
        bool okU = dk_parse_uint(L(c->s), c->base, &u);
        if (okU != (c->ok_u != 0) || (okU && u != c->uval)) BAD("uint case %zu: \"%s\" base %d: ok=%d u=%llu want ok=%d %llu", i, show(c->s), c->base, okU, (unsigned long long)u, c->ok_u, c->uval);
    }
    i64 v;
    CHECK(dk_parse_int(DK_S("12"), 10, &v, NULL) && v == 12);
    CHECK(!dk_parse_int(DK_S("99999999999999999999"), 10, &v, NULL));
}

